let body = $json.body ?? $json;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = null; } }
const missing = [];
const invalid = [];
const blank = (v) => v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return { valid: false, http_status: 400, response_body: { success: false, error_type: 'invalid_structure', message: 'El cuerpo debe ser un objeto JSON' } };
}
const incident = body.incident || {};
const action = body.action || {};
for (const [path, value] of [['event_id', body.event_id], ['incident.id', incident.id], ['incident.telegram_chat_id', incident.telegram_chat_id], ['action.id', action.id], ['action.proposed_action', action.proposed_action]]) {
  if (blank(value)) missing.push(path);
}
if (body.event_type !== 'agent.action.approved') invalid.push({ field: 'event_type', message: 'Debe ser agent.action.approved' });
if (!blank(incident.id) && !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(incident.id))) invalid.push({ field: 'incident.id', message: 'UUID no válido' });
if (!blank(action.id) && !/^\d+$/.test(String(action.id))) invalid.push({ field: 'action.id', message: 'Identificador no válido' });
const valid = missing.length === 0 && invalid.length === 0;
return {
  valid, missing_fields: missing, invalid_fields: invalid,
  event_id: body.event_id || null, incident_id: incident.id || null, action_id: action.id || null,
  reference: incident.reference || null, order_id: incident.order_id || null,
  customer_name: incident.customer_name || null, subject: incident.subject || 'Incidencia de soporte',
  telegram_chat_id: incident.telegram_chat_id || null, proposed_action: action.proposed_action || null,
  reviewed_by: action.reviewed_by || null, reviewed_at: action.reviewed_at || null,
  http_status: valid ? 200 : 400,
  response_body: valid ? null : { success: false, error_type: missing.length ? 'missing_fields' : 'invalid_values', missing_fields: missing, invalid_fields: invalid, message: 'Evento de aprobación inválido' }
};

const event = $('Validar aprobación').first().json;
const already = $json.action_exists === true && $json.execution_status === 'executed';
const should_send = $json.action_exists === true && $json.review_status === 'approved' && !already;
return {
  ...event, should_send,
  http_status: should_send || already ? 200 : 409,
  response_body: should_send ? null : {
    success: already, event_id: event.event_id, action_id: event.action_id,
    integration_status: already ? 'already_processed' : 'rejected',
    message: already ? 'La notificación ya fue enviada' : 'La acción no existe o no está aprobada'
  }
};

const event = $('Validar aprobación').first().json;
const failed = $json.execution_status === 'retry';
return {
  http_status: failed ? 503 : 200,
  response_body: {
    success: !failed, event_id: event.event_id, action_id: event.action_id,
    incident_id: event.incident_id, integration_status: failed ? 'retry' : 'completed',
    message: failed ? 'Telegram falló; el backend reintentará' : 'Notificación enviada y registrada'
  }
};
